import type { HTMLArkProps } from '@ark-ui/solid/factory';
import { ark } from '@ark-ui/solid/factory';
import { clsx } from 'clsx';
import { splitProps } from 'solid-js';
import styles from './Typeset.module.css';

type TypesetDataProps = {
  'data-scope'?: string;
  'data-part'?: string;
  'data-slot'?: string;
};

type TypesetRootProps = HTMLArkProps<'div'> & TypesetDataProps;

function TypesetRoot(props: TypesetRootProps) {
  const [local, others] = splitProps(props, [
    'asChild',
    'class',
    'data-scope',
    'data-part',
    'data-slot',
  ]);

  return (
    <ark.div
      asChild={local.asChild}
      {...others}
      data-scope="typeset"
      data-part="root"
      data-slot="typeset"
      class={clsx(styles.root, local.class)}
    />
  );
}

type TypesetScrollProps = HTMLArkProps<'div'> & TypesetDataProps;

function TypesetScroll(props: TypesetScrollProps) {
  const [local, others] = splitProps(props, [
    'aria-label',
    'aria-labelledby',
    'asChild',
    'class',
    'data-scope',
    'data-part',
    'data-slot',
    'role',
    'tabIndex',
  ]);

  return (
    <ark.div
      asChild={local.asChild}
      {...others}
      aria-label={local['aria-label']}
      aria-labelledby={local['aria-labelledby']}
      data-scope="typeset"
      data-part="scroll"
      data-slot="typeset-scroll"
      class={clsx(styles.scroll, local.class)}
      role={local.role ?? (local['aria-label'] || local['aria-labelledby'] ? 'region' : undefined)}
      tabIndex={local.tabIndex ?? 0}
    />
  );
}

const Typeset = Object.assign(TypesetRoot, {
  Root: TypesetRoot,
  Scroll: TypesetScroll,
});

export { Typeset };

/*
 * shadcn/typeset
 * https://ui.shadcn.com/docs/typeset.
 */

@layer base {
  .root {
    --moduix-typeset-font-body: inherit;
    --moduix-typeset-font-heading: var(--moduix-font-sans);
    --moduix-typeset-font-mono: var(--moduix-font-mono);
    --moduix-typeset-size: 1em;
    --moduix-typeset-leading: 1.75;
    --moduix-typeset-flow: 1.25em;
  }
}

@layer components {
  .root {
    font-family: var(--moduix-typeset-font-body);
    font-size: calc(var(--moduix-typeset-size) * 1.125);
    line-height: var(--moduix-typeset-leading);
    color: var(--moduix-color-foreground, currentColor);
    overflow-wrap: break-word;
    margin-trim: block-start;

    @media (min-width: 48rem), print {
      font-size: var(--moduix-typeset-size);
    }

  }

  .root
    *:not(
      :where(
        :global(.not-typeset),
        [data-not-typeset],
        :global(.not-typeset) *,
        [data-not-typeset] *
      )
    ) {
    /* Paragraphs. */
    &:where(p) {
      margin-block-start: var(--moduix-typeset-flow);
      margin-block-end: 0;
    }

    /* Headings. */
    &:where(h1, h2, h3, h4, h5, h6) {
      color: var(--moduix-color-foreground, currentColor);
      font-family: var(--moduix-typeset-font-heading);
      font-weight: 600;
      margin-block-end: 0;
    }
    &:where(h1) {
      font-size: 1.75em;
      line-height: 1.3;
      margin-block-start: var(--moduix-typeset-flow);
    }
    &:where(h2) {
      font-size: 1.25em;
      line-height: 1.4;
      margin-block-start: calc(var(--moduix-typeset-flow) * 1.4);
    }
    &:where(h3) {
      font-size: 1.125em;
      line-height: 1.45;
      margin-block-start: var(--moduix-typeset-flow);
    }
    &:where(h4) {
      font-size: 1em;
      line-height: 1.5;
      margin-block-start: var(--moduix-typeset-flow);
    }
    &:where(h5) {
      font-size: 0.875em;
      line-height: 1.5;
      font-weight: 500;
      color: var(--moduix-color-muted-foreground, color-mix(in oklab, currentColor 60%, transparent));
      margin-block-start: calc(var(--moduix-typeset-flow) / 0.875);
    }
    &:where(h6) {
      font-size: 0.8125em;
      line-height: 1.5;
      font-weight: 500;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      color: var(--moduix-color-muted-foreground, color-mix(in oklab, currentColor 60%, transparent));
      margin-block-start: calc(var(--moduix-typeset-flow) / 0.8125);
    }
    /* Anchors. */
    &:where([id]) {
      scroll-margin-block-start: var(--moduix-typeset-flow);
    }

    /* Headings own the space below them. */
    &:where(h1 + *, h2 + *, h3 + *, h4 + *, h5 + *, h6 + *) {
      margin-block-start: 1em;
    }
    &:where(:is(h1, h2, h3, h4) :is(code)) {
      font-size: 0.9em;
    }

    /* Links. */
    &:where(a) {
      color: inherit;
      font-weight: 500;
      text-decoration-line: underline;
      text-decoration-color: color-mix(in oklab, currentColor 30%, transparent);
    }
    &:where(a:hover) {
      text-decoration-color: currentColor;
    }
    &:where(a:focus-visible) {
      outline: 2px solid var(--moduix-color-ring, currentColor);
      outline-offset: 2px;
      border-radius: 0.125em;
    }
    &:where(:is(h1, h2, h3, h4, h5, h6) :is(a)) {
      font-weight: inherit;
    }

    /* Inline semantics. */
    &:where(strong, b) {
      font-weight: 600;
    }
    &:where(:is(h1, h2, h3, h4) :is(strong, b)) {
      font-weight: 600;
    }
    &:where(mark) {
      background-color: color-mix(
        in oklab,
        oklch(0.86 0.17 95) 40%,
        transparent
      );
      color: inherit;
      padding: 0.05em 0.15em;
      border-radius: 0.2em;
    }
    &:where(abbr[title]) {
      text-decoration-line: underline;
      text-decoration-style: dotted;
      text-underline-offset: 0.2em;
      cursor: help;
    }
    &:where(del, s) {
      color: var(--moduix-color-muted-foreground, color-mix(in oklab, currentColor 60%, transparent));
      text-decoration-line: line-through;
    }
    &:where(sup, sub) {
      font-size: 0.75em;
      line-height: 0;
      position: relative;
      vertical-align: baseline;
    }
    &:where(sup) {
      top: -0.5em;
    }
    &:where(sub) {
      bottom: -0.25em;
    }
    &:where(sup a) {
      text-decoration-line: none;
      font-weight: 500;
    }

    /* Lists. */
    &:where(ul) {
      list-style-type: disc;
    }
    &:where(ol) {
      list-style-type: decimal;
    }
    &:where(ul ul) {
      list-style-type: circle;
    }
    &:where(ul ul ul) {
      list-style-type: square;
    }
    &:where(ol[type="a" i]) {
      list-style-type: lower-alpha;
    }
    &:where(ol[type="i" i]) {
      list-style-type: lower-roman;
    }
    &:where(ol[type="A" s]) {
      list-style-type: upper-alpha;
    }
    &:where(ol[type="I" s]) {
      list-style-type: upper-roman;
    }
    &:where(ul, ol) {
      margin-block-start: var(--moduix-typeset-flow);
      margin-block-end: 0;
      padding-inline-start: 1.5em;
    }
    &:where(li) {
      margin-block-start: 0.5em;
      padding-inline-start: 0.4em;
    }
    &:where(li > p, li > ul, li > ol) {
      margin-block-start: 0.5em;
    }
    &:where(ul > li)::marker {
      color: var(--moduix-color-muted-foreground, color-mix(in oklab, currentColor 60%, transparent));
    }
    &:where(ol > li)::marker {
      color: var(--moduix-color-muted-foreground, color-mix(in oklab, currentColor 60%, transparent));
    }

    /* GFM task lists. */
    &:where(ul:global(.contains-task-list)) {
      list-style-type: none;
      padding-inline-start: 0.25em;
    }
    &:where(li:global(.task-list-item) > input[type="checkbox"]) {
      margin-inline-end: 0.5em;
      vertical-align: -0.1em;
      accent-color: var(--moduix-color-primary, currentColor);
    }

    /* Disclosures. */
    &:where(details) {
      margin-block-start: var(--moduix-typeset-flow);
      margin-block-end: 0;
    }
    &:where(summary) {
      cursor: pointer;
      font-weight: 500;
    }
    &:where(summary)::marker {
      color: var(--moduix-color-muted-foreground, color-mix(in oklab, currentColor 60%, transparent));
    }

    /* Keyboard keys. */
    &:where(kbd) {
      font-family: inherit;
      font-size: 0.85em;
      font-weight: 500;
      border: 1px solid var(--moduix-color-border, color-mix(in oklab, currentColor 20%, transparent));
      border-block-end-width: 2px;
      border-radius: min(calc(var(--moduix-radius-md, 0.5em) * 0.6), 0.35em);
      padding: 0.0625em 0.35em;
    }

    /* Definition lists. */
    &:where(dl) {
      margin-block-start: var(--moduix-typeset-flow);
      margin-block-end: 0;
    }
    &:where(dt) {
      font-weight: 500;
      margin-block-start: 1em;
    }
    &:where(dt + dt) {
      margin-block-start: 0.25em;
    }
    &:where(dd) {
      margin-block-start: 0.25em;
      margin-inline-start: 0;
      padding-inline-start: 1em;
      color: var(--moduix-color-muted-foreground, color-mix(in oklab, currentColor 60%, transparent));
    }

    /* Inline code. */
    &:where(:not(pre) > code) {
      background-color: var(
        --moduix-color-muted,
        color-mix(in oklab, currentColor 8%, transparent)
      );
      font-family: var(--moduix-typeset-font-mono);
      font-size: 0.85em;
      border-radius: min(calc(var(--moduix-radius-md, 0.5em) * 0.6), 0.35em);
      padding: 0.125em 0.3em;
    }

    /* Code blocks. */
    &:where(pre) {
      background-color: var(
        --moduix-color-muted,
        color-mix(in oklab, currentColor 8%, transparent)
      );
      font-family: var(--moduix-typeset-font-mono);
      font-size: 0.875em;
      line-height: 1.5;
      tab-size: 2;
      direction: ltr;
      border-radius: var(--moduix-radius-md, 0.5em);
      padding: 0.75em 1em;
      overflow-x: auto;
      margin-block-start: calc(var(--moduix-typeset-flow) / 0.875);
      margin-block-end: 0;
    }
    &:where(pre code) {
      background-color: transparent;
      font-family: inherit;
      font-size: inherit;
      padding: 0;
      border-radius: 0;
    }

    /* Blockquote. */
    &:where(blockquote) {
      border-inline-start: 2px solid var(--moduix-color-border, color-mix(in oklab, currentColor 20%, transparent));
      padding-inline-start: 1em;
      margin-block-start: var(--moduix-typeset-flow);
      margin-block-end: 0;
      margin-inline: 0;
    }

    /* Dividers. */
    &:where(hr) {
      border: 0;
      border-block-start: 1px solid var(--moduix-color-border, color-mix(in oklab, currentColor 20%, transparent));
      margin-block-start: calc(var(--moduix-typeset-flow) * 2.4);
      margin-block-end: 0;
    }
    &:where(hr + h1, hr + h2, hr + h3, hr + h4) {
      margin-block-start: var(--moduix-typeset-flow);
    }

    /* GFM footnotes. */
    &:where(:global(.footnotes), [data-footnotes]) {
      margin-block-start: calc(var(--moduix-typeset-flow) * 2);
      border-block-start: 1px solid var(--moduix-color-border, color-mix(in oklab, currentColor 20%, transparent));
      padding-block-start: var(--moduix-typeset-flow);
      font-size: 0.875em;
      color: var(--moduix-color-muted-foreground, color-mix(in oklab, currentColor 60%, transparent));
    }

    /* Math. */
    &:where(math[display="block"]) {
      margin-block-start: var(--moduix-typeset-flow);
      margin-block-end: 0;
      overflow-x: auto;
      overflow-y: hidden;
      padding-block: 0.25em;
    }

    /* Media. */
    &:where(img, video) {
      border-radius: var(--moduix-radius-md, 0.5em);
      max-width: 100%;
      height: auto;
      margin-block-start: var(--moduix-typeset-flow);
      margin-block-end: 0;
    }
    &:where(p img) {
      margin-block-start: 0;
    }
    &:where(figure) {
      margin-block-start: var(--moduix-typeset-flow);
      margin-block-end: 0;
      margin-inline: 0;
    }
    &:where(figcaption, caption) {
      color: var(--moduix-color-muted-foreground, color-mix(in oklab, currentColor 60%, transparent));
      font-size: 0.875em;
      text-align: center;
      margin-block-start: calc(0.75em / 0.875);
    }
    &:where(caption) {
      caption-side: bottom;
    }

    /* Tables. Separators sit on cells, not tr:last-child: append-safe.
       Bare tables stay real tables (keep their semantics) and wrap to fit. */
    &:where(table) {
      max-width: 100%;
      font-size: 1em;
      line-height: 1.5;
      font-variant-numeric: tabular-nums;
      border-collapse: separate;
      border-spacing: 0;
      border-block-end: 1px solid var(--moduix-color-border, color-mix(in oklab, currentColor 20%, transparent));
      margin-block-start: var(--moduix-typeset-flow);
      margin-block-end: 0;
    }

    /* Horizontal scroll for any wide block. Wrap it and the wrapper owns the
       flow margin. Tables shrink to fit, so widen the table to make it scroll
       instead of compress. */
    &:where(.scroll) {
      overflow-x: auto;
      margin-block-start: var(--moduix-typeset-flow);
    }
    &:where(.scroll > *) {
      margin-block-start: 0;
    }
    &:where(.scroll table) {
      width: max-content;
      max-width: none;
    }
    &:where(thead th) {
      font-weight: 500;
      text-align: start;
      white-space: nowrap;
      padding: 0.65em 1em;
    }
    &:where(:is(tbody, tfoot) :is(td, th)) {
      padding: 0.75em 1em;
      text-align: start;
      vertical-align: top;
      border-block-start: 1px solid var(--moduix-color-border, color-mix(in oklab, currentColor 20%, transparent));
    }
    &:where(tbody th, tfoot th) {
      font-weight: 500;
    }
    &:where(th:first-child, td:first-child) {
      padding-inline-start: 0;
    }
    &:where(th[align="center"], td[align="center"]) {
      text-align: center;
    }
    &:where(th[align="right"], td[align="right"]) {
      text-align: end;
    }

    /* Blocks inside list items keep the list's tighter rhythm. */
    &:where(li > blockquote, li > table, li > figure) {
      margin-block-start: 0.5em;
    }
    &:where(li > pre) {
      margin-block-start: calc(0.5em / 0.875);
    }

    @media print {
      &:where(pre, table, blockquote, figure) {
        break-inside: avoid;
      }
      &:where(h1, h2, h3, h4) {
        break-after: avoid;
      }
    }

    /* Forced colors strips the code background, so give it a border. */
    @media (forced-colors: active) {
      &:where(:not(pre) > code) {
        border: 1px solid;
      }
    }
  }

  /* First child adds no space above. Last so it wins ties. */
  .root
    > :where(:first-child):not(
      :where(
        :global(.not-typeset),
        [data-not-typeset],
        :global(.not-typeset) *,
        [data-not-typeset] *
      )
    ),
  .root
    > :where(:first-child)
    > :where(:first-child):not(
      :where(
        :global(.not-typeset),
        [data-not-typeset],
        :global(.not-typeset) *,
        [data-not-typeset] *
      )
    ),
  .root
    :where(
      li > :first-child,
      blockquote > :first-child,
      td > :first-child,
      th > :first-child,
      dd > :first-child,
      figure > :first-child,
      figure > picture > img
    ):not(
      :where(
        :global(.not-typeset),
        [data-not-typeset],
        :global(.not-typeset) *,
        [data-not-typeset] *
      )
    ) {
    margin-block-start: 0;
  }
  .scroll {
    box-sizing: border-box;
    max-width: 100%;
    overscroll-behavior-inline: contain;
  }

  .scroll:focus-visible {
    outline: var(--moduix-focus-ring-width, var(--moduix-border-width-md)) solid
      var(--moduix-color-ring);
    outline-offset: var(--moduix-focus-ring-inset-offset);
  }
}
